layer.css:
[data-ryt="footer"] { color: var(--ryt-bg); background-color: var(--ryt-text); border-top: 1px solid rgba(229, 231, 235, 0.1); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="button"] { color: rgb(255, 255, 255); background-color: rgb(21, 34, 55); border-radius: 9999px; box-shadow: rgba(0, 0, 0, 0.1) 0px 4px 6px -1px; font-family: var(--ryt-font-body); font-weight: 500; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(255, 255, 255); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 20px; padding-bottom: 8px; padding-left: 20px; transition: 0.3s }
[data-ryt="button"]:hover { box-shadow: 0 20px 25px -5px rgba(20, 33, 56, 0.302); transform: translateY(-2px) }
